function parseCSV(s){let rows=[],row=[],v='',q=false;for(let i=0;i<s.length;i++){let c=s[i];if(c==='"'){if(q&&s[i+1]==='"'){v+='"';i++}else q=!q}else if(!q&&(c===','||c==='\n')){row.push(v.replace(/\r$/,''));v='';if(c==='\n'){rows.push(row);row=[]}}else v+=c}if(q)throw Error('CSV ไม่สมบูรณ์');if(v||row.length){row.push(v);rows.push(row)}return rows}$('importBtn').onclick=()=>$('importFile').click();$('importFile').onchange=async()=>{let f=$('importFile').files[0];if(!f)return;let count=0,total=0;try{let rows;if(/\.xlsx$/i.test(f.name)){if(!window.XLSX)throw Error('โหลดระบบ Excel ไม่สำเร็จ');let w=XLSX.read(await f.arrayBuffer());rows=XLSX.utils.sheet_to_json(w.Sheets[w.SheetNames[0]],{header:1,raw:false,defval:''})}else rows=parseCSV((await f.text()).replace(/^\ufeff/,''));let [h,...r]=rows;if(!h.includes('title')||!h.includes('start'))throw Error('CSV ต้องมีหัวคอลัมน์ title,start,end,owner,place,details');let items=r.filter(a=>a.some(Boolean)).map(a=>Object.fromEntries(h.map((k,i)=>[k,a[i]||''])));total=items.length;if(events.length+total>999)throw Error('เกินจำนวน 999 รายการ');for(let e of items){e.start=e.start.includes('/')?parse(e.start):e.start;e.end=e.end?(e.end.includes('/')?parse(e.end):e.end):e.start;e.__backendId='';await api('create',{item:e});count++}$('adminMsg').textContent=`นำเข้าสำเร็จ ${count} รายการ`}catch(e){$('adminMsg').textContent=`นำเข้า ${count}/${total} รายการ: ${e.message}`}finally{$('importFile').value='';await load()}};
